# 40_fig4_fig5_v135.R  Figs. 4 and 5 of manuscript v135 redrawn with the v135 theme (9 pt type floor, bold axis titles). The benchmark is rerun by the
# first 42 lines of 39_b2_items.R (no fitting except S1 by fold) and Fig. 5 reads the saved scenarios of script 39. Shading of Fig. 5 as in script 26b (year 33 natural, year 10 planted).
L <- readLines("~/jobs/koa_final_eq_20261110/scripts/39_b2_items.R"); eval(parse(text = L[1:42])); MC <- fread("ms_v134b/scenarios_long_b2.csv"); dir.create("ms_v135", showWarnings = FALSE)
OR <- c(Natural = "#0072B2", Planted = "#D55E00"); LV <- c(Low = "#56B4E9", Median = "#009E73", High = "#CC79A7"); orig <- function(p) factor(ifelse(p == 1, "Planted", "Natural"), levels = names(OR))
theme_koa <- function() theme_classic(base_size = 11) + theme(axis.text = element_text(colour = "black", size = 9), axis.title = element_text(face = "bold", size = 9.5), legend.position = "bottom", legend.title = element_blank(), legend.text = element_text(size = 9), legend.key.size = unit(4, "mm"), plot.tag = element_text(face = "bold", size = 11), strip.background = element_blank(), strip.text = element_text(face = "bold", size = 10), plot.margin = margin(9, 6, 3, 3))
last[, origin := orig(planted)]; bp <- function(o, p, xl, yl, lim) { d <- data.table(o = last[[o]], p = last[[p]], origin = last$origin, h = last$h); mx <- if (is.null(lim)) max(c(d$o, d$p)) * 1.05 else lim
  ggplot(d, aes(p, o)) + annotate("ribbon", x = c(0, mx), ymin = c(0, 0.75 * mx), ymax = c(0, 1.25 * mx), fill = "#56B4E9", alpha = 0.25) + geom_abline(slope = 1, intercept = 0, linewidth = 0.3, colour = "#0072B2") + geom_point(aes(fill = h), shape = 21, size = 1.6, stroke = 0.2) + facet_wrap(~origin) +
    scale_fill_viridis_c(option = "plasma", end = 0.9, name = "Horizon (yr)  ", limits = range(last$h)) + coord_cartesian(xlim = c(0, mx), ylim = c(0, mx), expand = FALSE) + labs(x = xl, y = yl) }
fig4 <- (bp("o_surv", "p_surv", "Projected survival (proportion)", "Observed survival (proportion)", 1.05) / bp("o_qmd", "p_qmd", "Projected QMD (cm)", "Observed QMD (cm)", NULL) / bp("o_ba", "p_ba", "Projected basal area (m² ha⁻¹)", "Observed basal area (m² ha⁻¹)", NULL)) + plot_layout(guides = "collect") + plot_annotation(tag_levels = "a", tag_prefix = "(", tag_suffix = ")") & theme_koa() & theme(legend.title = element_text(size = 8), legend.key.width = unit(10, "mm"))
ggsave("ms_v135/Fig4_benchmark.png", fig4, width = 140, height = 190, units = "mm", dpi = 300, type = "cairo")
sc <- MC[site_dev == FALSE & var %in% c("BA", "QMD", "TPH")]; sc[, `:=`(origin = orig(planted), lev = factor(c(lo = "Low", md = "Median", hi = "High")[level], levels = names(LV)))]; vl <- c(BA = "Basal area (m² ha⁻¹)", QMD = "QMD (cm)", TPH = "Stems (ha⁻¹)"); sc[, vlab := factor(vl[var], levels = vl)]
shade <- data.table(origin = orig(c(0, 1)), xmin = c(33, 10), xmax = 100)
fig5 <- ggplot(sc, aes(year, point, colour = lev, fill = lev)) + geom_rect(data = shade, aes(xmin = xmin, xmax = xmax, ymin = -Inf, ymax = Inf), inherit.aes = FALSE, fill = "#F0E442", alpha = 0.18) + geom_ribbon(aes(ymin = p05, ymax = p95), alpha = 0.15, colour = NA) + geom_line(linewidth = 0.6) +
  facet_grid(vlab ~ origin, scales = "free_y", switch = "y") + scale_colour_manual(values = LV) + scale_fill_manual(values = LV) + labs(x = "Years from starting measurement", y = NULL) + theme_koa() + theme(strip.placement = "outside"); ggsave("ms_v135/Fig5_projections.png", fig5, width = 140, height = 170, units = "mm", dpi = 300, type = "cairo")
cat("Figs. 4 and 5 written to ms_v135\n")
